/* AC_NO_CROP_20260803_V3: preserve complete 9:16 outfit images in legacy 3:4 UI frames. */
(function applyApocalypseNoCropFixV3() {
  if (typeof document === 'undefined' || document.getElementById('apocalypse-no-crop-fix-v3')) return;
  const style = document.createElement('style');
  style.id = 'apocalypse-no-crop-fix-v3';
  style.textContent = `
    .outfit-card img,
    .thumb img,
    .slider-track img,
    .seo-static img,
    .related-card img {
      object-fit: contain !important;
      object-position: center center !important;
      background: transparent !important;
    }
    .outfit-card:hover img,
    .related-card:hover img {
      transform: none !important;
    }
  `;
  document.head.appendChild(style);
})();

/* AC_LAYOUT_STABILITY_20260804_V2
   Homepage only: render the Pinterest feed once. The four server-rendered
   starter cards are removed from index.html by the companion patch so the
   browser never paints a temporary 4-card layout before the real 32-card feed. */
(function applyApocalypseStableMasonryV2() {
  if (typeof document === 'undefined' || window.__acStableMasonryV2) return;

  const normalizedPath = (window.location.pathname || '/').replace(/\/+$/, '') || '/';
  const isHomepage = normalizedPath === '/' || normalizedPath === '/index.html';
  if (!isHomepage) return;

  window.__acStableMasonryV2 = true;

  function boot() {
    const grid = document.getElementById('outfit-grid');
    if (!grid || grid.dataset.acStableMasonry === '2') return;
    grid.dataset.acStableMasonry = '2';
    grid.classList.add('ac-stable-masonry', 'ac-grid-preparing');
    grid.setAttribute('aria-busy', 'true');

    const style = document.createElement('style');
    style.id = 'ac-layout-stability-20260804-v2';
    style.textContent = `
      /* Do not show a temporary or half-built grid. Card DOM is created first,
         then the complete grid is revealed on the next animation frame. */
      #outfit-grid.ac-grid-preparing {
        visibility: hidden !important;
        min-height: 100vh !important;
      }
      #outfit-grid.ac-stable-masonry {
        column-count: initial !important;
        column-gap: 0 !important;
        display: grid !important;
        grid-template-columns: repeat(4, minmax(0, 1fr)) !important;
        align-items: start !important;
        gap: 2px !important;
        padding: 0 2px 2px !important;
      }
      #outfit-grid.ac-stable-masonry > .ac-masonry-column {
        display: flex !important;
        min-width: 0 !important;
        flex-direction: column !important;
        gap: 2px !important;
      }
      #outfit-grid.ac-stable-masonry .outfit-card {
        display: block !important;
        width: 100% !important;
        margin: 0 !important;
        vertical-align: top !important;
        break-inside: avoid !important;
        -webkit-column-break-inside: avoid !important;
      }
      #outfit-grid.ac-stable-masonry .outfit-card.shimmer {
        contain: paint !important;
        opacity: 1 !important;
        transform: none !important;
        will-change: auto !important;
      }
      #outfit-grid.ac-stable-masonry .outfit-card:not(.shimmer) {
        animation: none !important;
        opacity: 1 !important;
        transform: none !important;
        will-change: auto !important;
      }
      #outfit-grid.ac-stable-masonry .outfit-card-link,
      #outfit-grid.ac-stable-masonry .outfit-card picture {
        display: block !important;
        width: 100% !important;
        height: 100% !important;
      }
      #outfit-grid.ac-stable-masonry .outfit-card img {
        display: block !important;
        width: 100% !important;
        height: 100% !important;
        object-fit: contain !important;
        object-position: center center !important;
        background: transparent !important;
      }
      @media (max-width: 768px) {
        #outfit-grid.ac-stable-masonry {
          grid-template-columns: repeat(2, minmax(0, 1fr)) !important;
        }
      }
      @media (prefers-reduced-motion: reduce) {
        #outfit-grid.ac-stable-masonry .outfit-card {
          animation: none !important;
          transition: none !important;
        }
      }
    `;
    document.head.appendChild(style);

    const nativeAppendChild = Node.prototype.appendChild;
    const nativeReplaceChildren = Element.prototype.replaceChildren;
    let renderedCards = [];
    let renderedColumnCount = window.innerWidth <= 768 ? 2 : 4;
    let revealToken = 0;

    /* Safety fallback: even if an old index.html still contains starter cards,
       remove them before the actual feed is generated. The index patch prevents
       them from being requested or painted in the first place. */
    nativeReplaceChildren.call(grid);

    function getLookNumber(card) {
      return Number(String(card?.dataset?.outfitId || '').replace(/\D/g, '')) || 0;
    }

    function getDimensions(card) {
      const img = card?.querySelector?.('img');
      const attrWidth = Number(img?.getAttribute('width'));
      const attrHeight = Number(img?.getAttribute('height'));
      if (attrWidth > 0 && attrHeight > 0) {
        return { width: attrWidth, height: attrHeight };
      }
      const lookNumber = getLookNumber(card);
      return lookNumber >= 41
        ? { width: 720, height: 1280 }
        : { width: 768, height: 1024 };
    }

    function reserveCardSpace(card, order) {
      const { width, height } = getDimensions(card);
      card.dataset.acOrder = String(order);
      card.style.aspectRatio = `${width} / ${height}`;

      const link = card.querySelector('.outfit-card-link');
      const picture = card.querySelector('picture');
      const img = card.querySelector('img');
      if (link) link.style.aspectRatio = `${width} / ${height}`;
      if (picture) picture.style.aspectRatio = `${width} / ${height}`;
      if (img) {
        img.width = width;
        img.height = height;
        img.style.aspectRatio = `${width} / ${height}`;
      }
      return height / width;
    }

    function revealCompleteGrid() {
      const token = ++revealToken;
      requestAnimationFrame(() => {
        if (token !== revealToken) return;
        grid.classList.remove('ac-grid-preparing');
        grid.style.minHeight = '';
        grid.setAttribute('aria-busy', 'false');
      });
    }

    function makeStableColumns(cards, requestedColumnCount) {
      const columnCount = requestedColumnCount || (window.innerWidth <= 768 ? 2 : 4);
      const columns = Array.from({ length: columnCount }, () => {
        const column = document.createElement('div');
        column.className = 'ac-masonry-column';
        return column;
      });
      const estimatedHeights = Array(columnCount).fill(0);

      cards.forEach((card, index) => {
        const ratioHeight = reserveCardSpace(card, index);
        let targetColumn;
        if (index < columnCount) {
          targetColumn = index;
        } else {
          const shortest = Math.min(...estimatedHeights);
          targetColumn = estimatedHeights.indexOf(shortest);
        }
        nativeAppendChild.call(columns[targetColumn], card);
        estimatedHeights[targetColumn] += ratioHeight + 0.01;
      });

      renderedCards = cards;
      renderedColumnCount = columnCount;
      nativeReplaceChildren.call(grid, ...columns);
      revealCompleteGrid();
    }

    function collectIncomingCards(node) {
      if (!node) return [];
      if (node.nodeType === Node.DOCUMENT_FRAGMENT_NODE) {
        return Array.from(node.children).filter(el => el.classList?.contains('outfit-card'));
      }
      return node.classList?.contains('outfit-card') ? [node] : [];
    }

    grid.appendChild = function stableGridAppend(node) {
      const incoming = collectIncomingCards(node)
        .filter(card => !card.classList.contains('outfit-card--placeholder'));

      if (incoming.length) {
        const existing = Array.from(grid.querySelectorAll('.outfit-card'))
          .filter(card => !card.classList.contains('outfit-card--placeholder'));
        const combined = existing.concat(incoming.filter(card => !existing.includes(card)));
        makeStableColumns(combined);
        return node;
      }
      return nativeAppendChild.call(grid, node);
    };

    let resizeTimer = 0;
    window.addEventListener('resize', function stableMasonryResize() {
      clearTimeout(resizeTimer);
      resizeTimer = window.setTimeout(() => {
        const nextColumnCount = window.innerWidth <= 768 ? 2 : 4;
        if (nextColumnCount === renderedColumnCount || !renderedCards.length) return;
        const ordered = [...renderedCards].sort(
          (a, b) => Number(a.dataset.acOrder || 0) - Number(b.dataset.acOrder || 0)
        );
        makeStableColumns(ordered, nextColumnCount);
      }, 120);
    }, { passive: true });
  }

  if (document.readyState === 'loading') boot();
  else boot();
})();


/* AC_STYLE_LAYOUT_STABILITY_20260804_V1
   The five /style/ pages keep their own Pinterest layout. This patch only
   reserves each image's true ratio before the file finishes loading; it does
   not rebuild or rebalance the page after every image load. */
(function applyStylePageLayoutStabilityV1() {
  if (typeof document === 'undefined' || window.__acStyleLayoutStabilityV1) return;

  const normalizedPath = (window.location.pathname || '').replace(/\/+$/, '');
  const isStylePage = /^\/style\/(dark-feminine|egirl|goth|baddie-streetwear|punk)\.html$/.test(normalizedPath);
  if (!isStylePage) return;

  window.__acStyleLayoutStabilityV1 = true;

  const style = document.createElement('style');
  style.id = 'ac-style-layout-stability-20260804-v1';
  style.textContent = `
    .outfit-card.shimmer {
      contain: paint !important;
      opacity: 1 !important;
      transform: none !important;
      will-change: auto !important;
    }
    .outfit-card,
    .outfit-card:not(.shimmer) {
      animation: none !important;
      transform: none !important;
      will-change: auto !important;
    }
    .outfit-card-link,
    .outfit-card picture {
      display: block !important;
      width: 100% !important;
    }
    .outfit-card img {
      display: block !important;
      width: 100% !important;
      height: auto !important;
      object-fit: contain !important;
      object-position: center center !important;
      background: transparent !important;
    }
  `;
  document.head.appendChild(style);

  function getLookNumber(card) {
    return Number(String(card?.dataset?.outfitId || '').replace(/\D/g, '')) || 0;
  }

  function reserveCard(card) {
    if (!card || card.dataset.acRatioReserved === '1') return;
    const img = card.querySelector('img');
    if (!img) return;

    let width = Number(img.getAttribute('width'));
    let height = Number(img.getAttribute('height'));
    if (!(width > 0 && height > 0)) {
      const lookNumber = getLookNumber(card);
      width = lookNumber >= 41 ? 720 : 768;
      height = lookNumber >= 41 ? 1280 : 1024;
      img.width = width;
      img.height = height;
    }

    const ratio = `${width} / ${height}`;
    const link = card.querySelector('.outfit-card-link');
    const picture = card.querySelector('picture');
    if (link) link.style.aspectRatio = ratio;
    if (picture) picture.style.aspectRatio = ratio;
    img.style.aspectRatio = ratio;
    card.dataset.acRatioReserved = '1';
  }

  function reserveAll(root = document) {
    root.querySelectorAll?.('.outfit-card').forEach(reserveCard);
  }

  reserveAll();
  const observer = new MutationObserver(records => {
    records.forEach(record => {
      record.addedNodes.forEach(node => {
        if (node.nodeType !== Node.ELEMENT_NODE) return;
        if (node.matches?.('.outfit-card')) reserveCard(node);
        reserveAll(node);
      });
    });
  });
  observer.observe(document.documentElement, { childList: true, subtree: true });

  window.addEventListener('load', () => {
    reserveAll();
    window.setTimeout(() => observer.disconnect(), 2000);
  }, { once: true });
})();
